WITH returns_agg AS (SELECT sr.sr_customer_sk, sr.sr_cdemo_sk, sr.sr_reason_sk, SUM(sr.sr_return_amt) AS total_return_amt, SUM(sr.sr_net_loss) AS total_net_loss, COUNT(*) AS return_cnt FROM store_returns sr GROUP BY sr.sr_customer_sk, sr.sr_cdemo_sk, sr.sr_reason_sk HAVING SUM(sr.sr_return_amt) > 100), customer_info AS (SELECT c.c_customer_sk, c.c_birth_year, cd.cd_demo_sk, cd.cd_purchase_estimate FROM customer c JOIN customer_demographics cd ON c.c_current_cdemo_sk = cd.cd_demo_sk WHERE c.c_birth_year > 1950), sales_agg AS (SELECT ws.ws_bill_customer_sk AS customer_sk, ws.ws_warehouse_sk, SUM(ws.ws_sales_price) AS total_sales_price, AVG(ws.ws_quantity) AS avg_quantity FROM web_sales ws GROUP BY ws.ws_bill_customer_sk, ws.ws_warehouse_sk) SELECT w.w_warehouse_name, r.r_reason_desc, COUNT(DISTINCT ra.sr_customer_sk) AS num_customers, SUM(ra.total_return_amt) AS total_return_amount, SUM(ra.total_net_loss) AS total_net_loss, AVG(ci.cd_purchase_estimate) AS avg_purchase_estimate, SUM(sa.total_sales_price) AS total_web_sales_price, AVG(sa.avg_quantity) AS avg_web_quantity, RANK() OVER (PARTITION BY r.r_reason_desc ORDER BY SUM(ra.total_net_loss) DESC) AS loss_rank FROM returns_agg ra JOIN customer_info ci ON ra.sr_customer_sk = ci.c_customer_sk JOIN reason r ON ra.sr_reason_sk = r.r_reason_sk JOIN sales_agg sa ON ra.sr_customer_sk = sa.customer_sk JOIN warehouse w ON sa.ws_warehouse_sk = w.w_warehouse_sk WHERE ra.total_return_amt > 200 GROUP BY w.w_warehouse_name, r.r_reason_desc HAVING SUM(ra.total_net_loss) > 500 ORDER BY total_net_loss DESC LIMIT 10
